#include <iostream>
#include <vector>
#include <unordered_set>

using namespace std;

struct Point {
    long long x, y;

    bool operator==(const Point& other) const {
        return x == other.x && y == other.y;
    }
};

struct State {
    long long x, y;
    int dir;

    bool operator==(const State& other) const {
        return x == other.x && y == other.y && dir == other.dir;
    }
};

struct PointHash {
    size_t operator()(const Point& p) const {
        size_t h1 = hash<long long>{}(p.x);
        size_t h2 = hash<long long>{}(p.y);
        return h1 ^ (h2 + 0x9e3779b97f4a7c15ULL + (h1 << 6) + (h1 >> 2));
    }
};

struct StateHash {
    size_t operator()(const State& s) const {
        size_t h = PointHash{}({s.x, s.y});
        size_t hd = hash<int>{}(s.dir);
        return h ^ (hd + 0x9e3779b97f4a7c15ULL + (h << 6) + (h >> 2));
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> t(n);
    for (int& value : t) {
        cin >> value;
    }

    const int dx[8] = {0, 1, 1, 1, 0, -1, -1, -1};
    const int dy[8] = {1, 1, 0, -1, -1, -1, 0, 1};

    unordered_set<State, StateHash> current, next;
    unordered_set<Point, PointHash> used;

    current.insert({0, 0, 0});

    for (int i = 0; i < n; ++i) {
        next.clear();

        for (const State& state : current) {
            long long x = state.x;
            long long y = state.y;

            for (int j = 0; j < t[i]; ++j) {
                x += dx[state.dir];
                y += dy[state.dir];
                used.insert({x, y});
            }

            next.insert({x, y, (state.dir + 1) % 8});
            next.insert({x, y, (state.dir + 7) % 8});
        }

        current.swap(next);
    }

    cout << used.size() << '\n';
    return 0;
}

